import glob,re
best={}
for f in glob.glob('results/eval_*.csv'):
    tag=re.sub(r'^eval_|\.csv$','',f.split('/')[-1])
    d=pd.read_csv(f); n='dataset' if 'dataset' in d.columns else d.columns[0]
